impl Serialize for Reader<'_> {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeSeq;
        let mut seq = serializer.serialize_seq(Some(self.instruction_count))?;
        let mut reader = Self { bytecode: self.bytecode, cursor: 0, instruction_count: self.instruction_count };

        while reader.cursor < self.bytecode.len() {
            let offset = reader.cursor;
            let instruction = reader
                .read()
                .map_err(serde::ser::Error::custom)?;
            seq.serialize_element(&InstructionJsonView { instruction, offset })?;
        }

        seq.end()
    }
}

impl serde_text::Serialize for Reader<'_> {
    fn serialize(&self, serializer: &mut serde_text::Serializer) -> fmt::Result {
        use fmt::Write;

        if self.instruction_count == 0 {
            return writeln!(serializer, "(empty)");
        }

        let offset_width = format!("{}", self.bytecode.len()).len().max(3);

        match serializer.format() {
            serde_text::Format::Simple => {
                let mut reader = Self { bytecode: self.bytecode, cursor: 0, instruction_count: self.instruction_count };

                while reader.cursor < self.bytecode.len() {
                    let offset = reader.cursor;
                    let instruction = reader.read().map_err(|_| fmt::Error)?;
                    write_instruction_simple(serializer, &instruction, offset, offset_width)?;
                }

                Ok(())
            }
            serde_text::Format::Pretty => {
                let mut name_width: usize = 0;
                let mut operand_widths = [0usize; MAX_OPERANDS];

                {
                    let mut reader = Self { bytecode: self.bytecode, cursor: 0, instruction_count: self.instruction_count };

                    while reader.cursor < self.bytecode.len() {
                        let instruction = reader.read().map_err(|_| fmt::Error)?;
                        let (instruction_name_width, operand_count, instruction_operand_widths) = measure_instruction(&instruction);
                        name_width = name_width.max(instruction_name_width);
                        for operand_index in 0..operand_count {
                            operand_widths[operand_index] = operand_widths[operand_index].max(instruction_operand_widths[operand_index]);
                        }
                    }
                }

                let mut reader = Self { bytecode: self.bytecode, cursor: 0, instruction_count: self.instruction_count };

                while reader.cursor < self.bytecode.len() {
                    let offset = reader.cursor;
                    let instruction = reader.read().map_err(|_| fmt::Error)?;
                    write_instruction_pretty(
                        serializer,
                        &instruction,
                        offset,
                        offset_width,
                        name_width,
                        &operand_widths,
                    )?;
                }

                Ok(())
            }
        }
    }
}

/// - `Offset` — frame-relative byte offset, prefixed with `o` in text format.
/// - `Immutable` — literal value embedded in bytecode, prefixed with `i`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum OperandKind {
    Offset,
    Immutable,
}

struct JsonOperand {
    name: &'static str,
    data: u64,
    kind: OperandKind,
}

impl Serialize for JsonOperand {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeMap;
        let mut map = serializer.serialize_map(Some(3))?;
        map.serialize_entry("name", self.name)?;
        map.serialize_entry("data", &self.data)?;
        map.serialize_entry("kind", &self.kind)?;
        map.end()
    }
}

struct JsonOperandSlice<'a>(&'a [JsonOperand]);

impl Serialize for JsonOperandSlice<'_> {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeSeq;
        let mut seq = serializer.serialize_seq(Some(self.0.len()))?;
        for operand in self.0 {
            seq.serialize_element(operand)?;
        }
        seq.end()
    }
}

